# BEGIN fix (133 / 215) for 'file_ownership_var_log_audit'
###############################################################################
(>&2 echo "Remediating rule 133/215: 'file_ownership_var_log_audit'")

if `grep -q ^log_group /etc/audit/auditd.conf` ; then
